import { EffectComponent } from "./effect-component";
import { EffectModel } from "./effect-model";

import type { Component } from "solid-js";

export const EffectExample: Component = () => {
	return (
		<div class="flex flex-col m-2">
			<div class="flex flex-row mb-2">
				<EffectComponent
					action={(setter) => setter((value) => `${value} Foo`)}
					name="Add Foo"
				/>
				<EffectComponent
					action={(setter) => setter((value) => `${value} Bar`)}
					name="Add Bar"
				/>
				<EffectComponent
					action={(setter) => setter("")}
					name="Clear Value"
				/>
			</div>
			<div class="img-dropdown-box p-2 w-128">{EffectModel.value()}</div>
		</div>
	);
};
